test("alerts at 10:09 when six payments fall inside one period", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:09:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:09:00Z" });
});

test("does not alert when the sixth payment is exactly 10 minutes after the first", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:10:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});

test("does not alert when there are only five payments", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});

test("does not alert when there are no payments", function () {
  var actual = code.checkCardPayments({ paymentTimes: [] });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});

test("alerts at 10:11 when that payment is the sixth inside its period", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:06:00Z",
      "2024-01-01T10:08:00Z",
      "2024-01-01T10:10:00Z",
      "2024-01-01T10:11:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:11:00Z" });
});

test("alerts at 10:17 when six payments cluster after one outside the period", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:12:00Z",
      "2024-01-01T10:13:00Z",
      "2024-01-01T10:14:00Z",
      "2024-01-01T10:15:00Z",
      "2024-01-01T10:16:00Z",
      "2024-01-01T10:17:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: true, alertTime: "2024-01-01T10:17:00Z" });
});

test("does not alert when every period holds at most five payments", function () {
  var actual = code.checkCardPayments({
    paymentTimes: [
      "2024-01-01T10:00:00Z",
      "2024-01-01T10:01:00Z",
      "2024-01-01T10:02:00Z",
      "2024-01-01T10:03:00Z",
      "2024-01-01T10:04:00Z",
      "2024-01-01T10:14:00Z",
      "2024-01-01T10:15:00Z",
      "2024-01-01T10:16:00Z",
      "2024-01-01T10:17:00Z",
      "2024-01-01T10:18:00Z"
    ]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});

test("does not alert when there is only one payment", function () {
  var actual = code.checkCardPayments({
    paymentTimes: ["2024-01-01T10:00:00Z"]
  });
  assert.deepEqual(actual, { alert: false, alertTime: null });
});
